<?php declare(strict_types=1); namespace Modules\PromptEngine\Services\ImageProviders; use Modules\PromptEngine\Interfaces\PlatformPromptProviderInterface; final class StableDiffusionPromptProvider extends AbstractPromptProvider implements PlatformPromptProviderInterface { public function platform():string{return 'stable-diffusion';} public function build(array $c):array{[$w,$h]=match($c['aspect_ratio']){'1:1'=>[1024,1024],'16:9'=>[1344,768],'9:16'=>[768,1344],'4:5'=>[896,1120],'3:4'=>[896,1152],default=>[832,1216]};return ['prompt'=>$this->base($c),'positive_prompt'=>$this->base($c),'negative_prompt'=>$this->avoid($c),'recommended_settings'=>['recommended_width'=>$w,'recommended_height'=>$h,'recommended_steps'=>30,'recommended_cfg_scale'=>6.5,'recommended_sampler'=>'DPM++ 2M Karras']];} }
